import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useContext } from 'react';
import AuthContext from '../context/AuthContext';
import axios from 'axios';
import 'bootstrap/dist/css/bootstrap.min.css';
import '@fortawesome/fontawesome-free/css/all.min.css';

export default function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loginAs, setLoginAs] = useState('user'); // cosmetic only
  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('http://localhost:5000/api/auth/login', { email, password });
      
      // Role comes from backend (res.data.user.role)
      login(res.data);
      navigate('/quizzes');
    } catch (err) {
      alert('Login failed: ' + (err.response?.data?.error || 'Invalid credentials'));
    }
  };

  return (
    <div className="login-container" style={{ 
      margin: 0, 
      padding: 0, 
      height: '100vh', 
      background: '#60a3bc' 
    }}>
      <div className="d-flex justify-content-center align-items-center h-100">
        <div className="user_card" style={{
          height: '450px', // taller for dropdown
          width: '350px',
          background: '#f39c12',
          position: 'relative',
          display: 'flex',
          justifyContent: 'center',
          flexDirection: 'column',
          padding: '10px',
          boxShadow: '0 4px 8px 0 rgba(0,0,0,0.2), 0 6px 20px 0 rgba(0,0,0,0.19)',
          borderRadius: '5px'
        }}>
          <div className="d-flex justify-content-center">
            <div className="brand_logo_container" style={{
              position: 'absolute',
              height: '170px',
              width: '170px',
              top: '-75px',
              borderRadius: '50%',
              background: '#60a3bc',
              padding: '10px',
              textAlign: 'center'
            }}>
              <img 
                src="https://cdn-icons-png.flaticon.com/512/2972/2972185.png" 
                className="brand_logo" 
                alt="Logo"
                style={{
                  height: '150px',
                  width: '150px',
                  borderRadius: '50%',
                  border: '2px solid white'
                }}
              />
            </div>
          </div>

          <div className="d-flex justify-content-center form_container" style={{ marginTop: '100px' }}>
            <form onSubmit={handleSubmit} style={{ width: '100%' }}>
              {/* 👇 Login As Dropdown */}
              <div className="form-group mb-2">
                <select
                  className="form-control"
                  value={loginAs}
                  onChange={(e) => setLoginAs(e.target.value)}
                  style={{
                    background: '#fff',
                    border: '1px solid #ced4da',
                    borderRadius: '0.25rem',
                    padding: '0.375rem 0.75rem'
                  }}
                >
                  <option value="user">Login as User</option>
                  <option value="admin">Login as Admin</option>
                </select>
              </div>

              <div className="input-group mb-3">
                <div className="input-group-append">
                  <span className="input-group-text" style={{ 
                    background: '#c0392b', 
                    color: 'white', 
                    border: '0', 
                    borderRadius: '0.25rem 0 0 0.25rem' 
                  }}>
                    <i className="fas fa-user"></i>
                  </span>
                </div>
                <input
                  type="email"
                  className="form-control input_user"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="Email"
                  required
                  style={{ boxShadow: 'none', outline: '0px' }}
                />
              </div>

              <div className="input-group mb-2">
                <div className="input-group-append">
                  <span className="input-group-text" style={{ 
                    background: '#c0392b', 
                    color: 'white', 
                    border: '0', 
                    borderRadius: '0.25rem 0 0 0.25rem' 
                  }}>
                    <i className="fas fa-key"></i>
                  </span>
                </div>
                <input
                  type="password"
                  className="form-control input_pass"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="Password"
                  required
                  style={{ boxShadow: 'none', outline: '0px' }}
                />
              </div>

              <div className="d-flex justify-content-center mt-3 login_container" style={{ padding: '0 2rem' }}>
                <button 
                  type="submit" 
                  className="btn login_btn" 
                  style={{ 
                    width: '100%', 
                    background: '#c0392b', 
                    color: 'white' 
                  }}
                >
                  Login
                </button>
              </div>
            </form>
          </div>

          <div className="mt-4 text-center">
            <div className="links">
              Don't have an account?{' '}
              <a href="/register" className="ml-2" style={{ color: '#fff', textDecoration: 'underline' }}>
                Sign Up
              </a>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
